import React,{useEffect,useMemo,useRef,useState} from 'react';
import {LayoutDashboard,Building2,BriefcaseBusiness,FolderKanban,Users,UserRoundCog,FileText,Images,MessageSquare,ShieldCheck,Settings,LogOut,Menu,Plus,Search,Eye,Trash2,Edit3,Save,Upload,Download,RefreshCw,X,ExternalLink,FlaskConical,Package,WalletCards,Handshake,Repeat2,EyeOff,ArrowLeft,Mail,LockKeyhole} from 'lucide-react';
import {BilarLogo} from '../components/BilarLogo';
const DEFAULT_LOGIN_BACKGROUND='/admin/bilar_admin_tech_environment.webp';
import {useSiteData} from '../context/SiteContext';
import {BilarProduct,BlogPost,Project,RevenueStream,Service,Specialist,TeamMember,LabProject,CareerOpening,Partner,ProductOperation,AdminRole} from '../types';
import ContentExtrasEditor from '../components/ContentExtrasEditor';
import {cloudinaryConfigured, uploadOptimizedImage} from '../lib/cloudinary';

const nav=[['dashboard','Dashboard',LayoutDashboard],['empresa','Empresa',Building2],['servicos','Bilar Services',BriefcaseBusiness],['products','Bilar Products',Package],['labs','Bilar Labs',FlaskConical],['receitas','Receitas & Modelo',WalletCards],['projectos','Projectos & Casos',FolderKanban],['equipa','Equipa',Users],['carreiras','Carreiras',Users],['parceiros','Parceiros',Handshake],['especialistas','Especialistas',UserRoundCog],['blog','Insights',FileText],['media','Media Library',Images],['contactos','CRM / Leads',MessageSquare],['utilizadores','Utilizadores & Permissões',ShieldCheck],['configuracoes','Configurações',Settings]] as const;
const imgFor=(p:Project)=>p.image||'/products/agro-sentinela.svg';
const statusLabel=(s:string)=>({published:'Publicado',draft:'Rascunho',archived:'Arquivado',new:'Novo',read:'Lido',replied:'Respondido'} as any)[s]||s;
const Pill=({children,kind='blue'}:{children:React.ReactNode;kind?:string})=><span className={`admin-pill ${kind}`}>{children}</span>;
const Modal=({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode})=><div className="admin-modal-backdrop"><div className="admin-modal"><div className="admin-modal-head"><div><div className="admin-eyebrow">Bilar DigitalTech</div><h2>{title}</h2></div><button onClick={onClose}><X/></button></div>{children}</div></div>;
const Field=({label,value,onChange,area=false,placeholder=''}:{label:string;value:string;onChange:(v:string)=>void;area?:boolean;placeholder?:string;key?:React.Key})=><label className="admin-field"><span>{label}</span>{area?<textarea value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>:<input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}</label>;

const PasswordField=({label,value,onChange,placeholder='Palavra-passe'}:{label:string;value:string;onChange:(v:string)=>void;placeholder?:string})=>{const[show,setShow]=useState(false);return <label className="admin-field admin-password-field"><span>{label}</span><div className="admin-password-wrap"><input type={show?'text':'password'} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} autoComplete={label.toLowerCase().includes('confirm')?'new-password':'current-password'}/><button type="button" aria-label={show?'Ocultar palavra-passe':'Mostrar palavra-passe'} onClick={()=>setShow(!show)}>{show?<Eye size={17}/>:<EyeOff size={17}/>}</button></div></label>};const GoogleGIcon=()=> <svg width="17" height="17" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.35 12.27c0-.7-.06-1.37-.18-2.02H12v3.82h5.24a4.48 4.48 0 0 1-1.94 2.94v2.45h3.14c1.84-1.69 2.91-4.17 2.91-7.19Z"/><path fill="#34A853" d="M12 21.55c2.63 0 4.84-.87 6.45-2.36l-3.14-2.45c-.87.58-1.98.92-3.31.92-2.54 0-4.69-1.72-5.46-4.03H3.29v2.53A9.74 9.74 0 0 0 12 21.55Z"/><path fill="#FBBC05" d="M6.54 13.63A5.85 5.85 0 0 1 6.23 12c0-.57.1-1.12.31-1.63V7.84H3.29A9.72 9.72 0 0 0 2.25 12c0 1.56.37 3.03 1.04 4.33l3.25-2.7Z"/><path fill="#EA4335" d="M12 6.34c1.43 0 2.71.49 3.72 1.46l2.79-2.79C16.83 3.46 14.63 2.45 12 2.45a9.74 9.74 0 0 0-8.71 5.39l3.25 2.53C7.31 8.06 9.46 6.34 12 6.34Z"/></svg>;

const ImageField=({label,value,onChange,help='PNG, JPG, WEBP ou SVG'}:{label:string;value?:string;onChange:(v:string)=>void;help?:string})=>{
 const input=useRef<HTMLInputElement>(null); const [busy,setBusy]=useState(false); const [progress,setProgress]=useState(0); const [error,setError]=useState('');
 const choose=async(file?:File)=>{ if(!file)return; if(!file.type.startsWith('image/')){setError('Escolha um ficheiro de imagem.');return;} if(file.size>10*1024*1024){setError('A imagem original deve ter no máximo 10 MB.');return;} if(!cloudinaryConfigured){setError('Uploads gratuitos requerem a configuração do Cloudinary. Pode usar “Usar URL” enquanto isso.');return;} setError('');setBusy(true);setProgress(0); try{onChange(await uploadOptimizedImage(file,setProgress));}catch(e:any){setError(e?.message==='upload-timeout'?'O carregamento ultrapassou 30 s. Verifique a ligação ou a configuração do Cloudinary. Pode usar “Usar URL”.':'Falha no upload. Verifique a configuração do Cloudinary ou use “Usar URL”.');}finally{setBusy(false);setProgress(0)} };
 const [url,setUrl]=useState('');
 const applyUrl=()=>{const u=url.trim();if(!u){setError('Introduza o URL da imagem.');return;}setError('');setBusy(true);const probe=new Image();let done=false;const t=window.setTimeout(()=>{if(!done){done=true;setBusy(false);setError('O URL demorou demasiado a responder.');}},5000);probe.onload=()=>{if(done)return;done=true;window.clearTimeout(t);onChange(u);setUrl('');setBusy(false)};probe.onerror=()=>{if(done)return;done=true;window.clearTimeout(t);setBusy(false);setError('O URL não parece apontar para uma imagem válida.');};probe.src=u;};
 return <div className="admin-image-field"><div className="admin-image-head"><span>{label}</span><small>{help} · também pode usar um URL de imagem</small></div><div className="admin-image-box">{value?<img src={value} alt="Pré-visualização" loading="lazy"/>:<div className="admin-image-empty"><Images size={25}/><span>Nenhuma imagem seleccionada</span></div>}<div className="admin-image-actions"><input ref={input} hidden type="file" accept="image/*,.svg" onChange={e=>choose(e.target.files?.[0])}/><button type="button" className="admin-secondary" onClick={()=>input.current?.click()} disabled={busy}><Upload size={15}/>{busy?`A carregar ${progress}%`:value?'Substituir imagem':'Fazer upload'}</button>{value&&<button type="button" className="admin-secondary" onClick={()=>onChange('')} disabled={busy}><X size={15}/> Remover</button>}</div><div className="admin-image-url"><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://exemplo.com/imagem.jpg" disabled={busy}/><button type="button" className="admin-secondary" onClick={applyUrl} disabled={busy}>Usar URL</button></div></div>{error&&<div className="admin-error">{error}</div>}</div>;
};
const GalleryField=({label,value,onChange}:{label:string;value?:string[];onChange:(v:string[])=>void})=>{const input=useRef<HTMLInputElement>(null);const files=value||[];const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[progress,setProgress]=useState(0);const choose=async(list:FileList|null)=>{if(!list)return;if(!cloudinaryConfigured){setError('Uploads gratuitos requerem a configuração do Cloudinary. Pode usar “Usar URL” enquanto isso.');return;}const accepted=Array.from(list).filter(f=>f.type.startsWith('image/')&&f.size<=5*1024*1024);if(!accepted.length){setError('Escolha imagens até 5 MB cada.');return;}setBusy(true);setError('');setProgress(0);try{const urls:string[]=[];for(let i=0;i<accepted.length;i++){urls.push(await uploadOptimizedImage(accepted[i],p=>setProgress(Math.round(((i+p/100)/accepted.length)*100))))}onChange([...files,...urls]);}catch(e:any){setError(e?.message==='upload-timeout'?'O carregamento ultrapassou 30 s. Verifique a ligação ou o Cloudinary.':'Não foi possível enviar a galeria para o Cloudinary.');}finally{setBusy(false);setProgress(0)}};return <div className="admin-image-field"><div className="admin-image-head"><span>{label}</span><small>Imagens optimizadas antes do upload.</small></div><div className="admin-gallery-grid">{files.map((url,i)=><div className="admin-gallery-item" key={i}><img src={url} alt={`Galeria ${i+1}`} loading="lazy"/><button type="button" onClick={()=>onChange(files.filter((_,j)=>j!==i))}><X size={14}/></button></div>)}<button type="button" className="admin-gallery-add" disabled={busy} onClick={()=>input.current?.click()}><Upload size={18}/><span>{busy?`A carregar ${progress}%`:'Adicionar'}</span></button></div>{error&&<div className="admin-error">{error}</div>}<input ref={input} hidden type="file" accept="image/*" multiple onChange={e=>choose(e.target.files)}/></div>};



export default function AdminApp(){
 const d=useSiteData(); const [page,setPage]=useState('dashboard'); const [sidebar,setSidebar]=useState(true); const [query,setQuery]=useState(''); const [loginUser,setLoginUser]=useState(''); const [loginPass,setLoginPass]=useState(''); const [loginError,setLoginError]=useState(''); const [resetMode,setResetMode]=useState(false);
 const counts={products:d.bilarProducts.length,revenue:d.revenueStreams.filter((x:RevenueStream)=>x.active!==false).length,projects:d.projects.length,services:d.services.filter(x=>x.active!==false).length,team:d.teamMembers.filter(x=>x.active!==false).length,specialists:d.specialists.filter(x=>x.active!==false).length,posts:d.blogPosts.filter(x=>x.status!=='archived').length,contacts:d.contactMessages.filter(x=>x.status==='new').length,media:d.mediaAssets.length};
  if(!d.authReady){
   return <div className="admin-auth admin-auth-login" style={{'--admin-auth-bg':`url("${DEFAULT_LOGIN_BACKGROUND}")`} as React.CSSProperties}><div className="admin-auth-loading"><div className="admin-auth-loading-card"><ShieldCheck size={22}/><strong>Verificar acesso seguro</strong><span>Aguarde enquanto confirmamos a sua sessão.</span></div></div></div>;
  }
  if(!d.isAdminAuthenticated){
   const savedBg=d.adminSettings.loginBackground;
   const loginBg=savedBg && !savedBg.startsWith('/assets/images/') ? savedBg : DEFAULT_LOGIN_BACKGROUND;
   return <div className="admin-auth admin-auth-login" style={{'--admin-auth-bg':`url("${loginBg}")`} as React.CSSProperties}>
     <div className="admin-auth-card">
       <section className="admin-auth-brand">
         <div className="admin-auth-brand-overlay"/>
         <div className="admin-auth-brand-content">
           <BilarLogo size="sm" theme="dark"/>
           <div className="admin-auth-kicker">GESTÃO BILAR</div>
           <Pill kind="green">ACESSO PROTEGIDO</Pill>
           <h1>Ideias que conectam.<br/><em>Soluções que transformam.</em></h1>
           <p>Centro de gestão da BILAR DigitalTech Solutions.</p>
           <div className="admin-auth-identity-line"><span/> Gestão interna · Bilar DigitalTech Solutions</div>
         </div>
       </section>
       <section className="admin-auth-form">
         {!resetMode&&<><div className="admin-auth-form-head"><div className="admin-auth-kicker">CENTRO DE GESTÃO</div><h2>Bem-vindo à Gestão Bilar</h2><p>Aceda à área administrativa para gerir o conteúdo da empresa.</p></div>
         <form onSubmit={async e=>{e.preventDefault();setLoginError('');const email=loginUser.trim();if(!email||!loginPass){setLoginError('Introduza o email e a palavra-passe.');return;}const result=await d.loginAdmin(email,loginPass);if(!result.ok)setLoginError(result.message||'Não foi possível entrar. Tente novamente.');}}>
           <Field label="Email profissional" value={loginUser} onChange={setLoginUser} placeholder="nome@empresa.com"/>
           <PasswordField label="Palavra-passe" value={loginPass} onChange={setLoginPass}/>
           {loginError&&<div className="admin-error">{loginError}</div>}
           <button type="submit" className="admin-primary full">Entrar no painel <ExternalLink size={16}/></button>
         </form>
         <div className="admin-auth-divider"><span>ou</span></div>
         <button type="button" className="admin-google-button" onClick={async()=>{setLoginError('');const result=await d.loginAdminWithGoogle();if(!result.ok)setLoginError(result.message||'Não foi possível entrar com Google.');}}><GoogleGIcon/> Continuar com Google</button>
         <div className="admin-auth-actions">
           <button type="button" className="admin-forgot-link" onClick={()=>{setLoginError('');setResetMode(true)}}>Esqueci-me da palavra-passe</button>
           
         </div></>}
         {resetMode&&<LocalOrFirebaseReset email={loginUser} setEmail={setLoginUser} firebaseReady={d.firebaseReady} onBack={()=>{setResetMode(false);setLoginError('')}} onMessage={(msg,ok)=>{setLoginError(ok?'':msg)}}/>}
         <div className="admin-auth-foot">Bilar DigitalTech Solutions · Centro de Gestão</div>
       </section>
     </div>
   </div>;
  }
  if(d.mustChangePassword) return <FirstPasswordChangeScreen onDone={()=>{}} onLogout={d.logoutAdmin}/>;
 const allowedNav=(id:string)=>{const r=d.currentAdminRole; if(r==='Super Admin')return true; if(r==='Admin')return !['utilizadores','configuracoes'].includes(id); if(r==='Editor')return ['dashboard','servicos','products','projectos','blog','media'].includes(id); if(r==='Team Manager')return ['dashboard','equipa','carreiras','parceiros','especialistas'].includes(id); return id==='dashboard';}; const visibleNav=nav.filter(([id])=>allowedNav(id));
 const searchItems=[...visibleNav.map(([id,label])=>({type:'Página',label:String(label),id})),...(d.bilarProducts||[]).map((x:any)=>({type:'Produto',label:x.title||x.name,id:'products'})),...(d.services||[]).map((x:any)=>({type:'Serviço',label:x.title||x.name,id:'servicos'})),...(d.projects||[]).map((x:any)=>({type:'Projecto',label:x.title||x.name,id:'projectos'})),...(d.teamMembers||[]).map((x:any)=>({type:'Equipa',label:x.name,id:'equipa'})),...(d.blogPosts||[]).map((x:any)=>({type:'Insight',label:x.title,id:'blog'}))];
 const content=<><Header page={page} query={query} setQuery={setQuery} sidebar={sidebar} setSidebar={setSidebar} onLogout={d.logoutAdmin} role={d.currentAdminRole||'Gestão'} searchItems={searchItems} onNavigate={setPage}/><div className={`admin-shell ${sidebar?'with-sidebar':''}`}><aside className={`admin-sidebar ${sidebar?'':'closed'}`}><div className="admin-side-brand"><div className="admin-side-section"><LayoutDashboard size={16}/><div><strong>Centro de Gestão</strong><span>Bilar DigitalTech Solutions</span></div></div></div><nav>{visibleNav.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>setPage(id)}><Icon size={18}/><span>{label}</span>{id==='contactos'&&counts.contacts>0&&<b>{counts.contacts}</b>}</button>)}</nav><div className="admin-side-bottom"><a href={import.meta.env.BASE_URL} target="_blank"><Eye size={16}/> Ver site público</a><button onClick={d.logoutAdmin}><LogOut size={16}/> Terminar sessão</button></div></aside><main className="admin-main">{page==='dashboard'&&<Dashboard counts={counts} data={d} go={setPage}/>} {page==='empresa'&&<Empresa data={d}/>} {page==='products'&&<Products data={d}/>} {page==='labs'&&<Labs data={d}/>} {page==='receitas'&&<Revenue data={d}/>} {page==='servicos'&&<Services data={d}/>} {page==='projectos'&&<Projects data={d}/>} {page==='equipa'&&<Team data={d}/>} {page==='carreiras'&&<Careers data={d}/>} {page==='parceiros'&&<Partners data={d}/>} {page==='especialistas'&&<Specialists data={d}/>} {page==='blog'&&<Blog data={d}/>} {page==='media'&&<Media data={d}/>} {page==='contactos'&&<Contacts data={d}/>} {page==='utilizadores'&&<UsersAdmin data={d}/>} {page==='configuracoes'&&<SettingsAdmin data={d}/>}</main></div></>;
 const adminBg=d.adminSettings.dashboardBackground; const adminLayout=d.adminSettings.dashboardLayout==='operations'?'operations':'corporate';
 return <div className={`admin-root admin-layout-${adminLayout}`} style={adminBg?{backgroundImage:`linear-gradient(rgba(237,244,248,.90),rgba(244,248,250,.95)),url(${adminBg})`}:undefined}>{content}</div>;
}

function Header({page,query,setQuery,sidebar,setSidebar,onLogout,role,searchItems,onNavigate}:{page:string;query:string;setQuery:(v:string)=>void;sidebar:boolean;setSidebar:(v:boolean)=>void;onLogout:()=>void;role:string;searchItems:{type:string;label:string;id:string}[];onNavigate:(id:string)=>void}){
 const results=query.trim()?searchItems.filter(x=>x.label.toLowerCase().includes(query.trim().toLowerCase())).slice(0,7):[];
 return <header className="admin-header"><div className="admin-header-left"><button className="icon-btn" aria-label="Menu" onClick={()=>setSidebar(!sidebar)}><Menu size={19}/></button><BilarLogo size="sm" theme="dark"/><div className="admin-header-context"><strong>Centro de Gestão</strong><span>Operações digitais Bilar</span></div></div><div className="admin-header-search-wrap"><div className="admin-header-search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Pesquisar no painel..." aria-label="Pesquisar no painel"/><kbd>⌘ K</kbd></div>{query.trim()&&<div className="admin-search-results">{results.length?results.map((x,i)=><button key={`${x.id}-${i}`} onClick={()=>{onNavigate(x.id);setQuery('')}}><span className="search-result-icon"><Search size={13}/></span><span><strong>{x.label}</strong><small>{x.type}</small></span><ExternalLink size={13}/></button>):<div className="admin-search-empty">Nenhum resultado encontrado.</div>}</div>}</div><div className="admin-header-right"><span className="admin-role-badge">{role}</span><span className="admin-header-page">{page==='dashboard'?'Visão geral':page}</span><button className="icon-btn" aria-label="Terminar sessão" title="Terminar sessão" onClick={onLogout}><LogOut size={18}/></button></div></header>
}
function PageIntro({eyebrow,title,text,action}:{eyebrow?:string;title:string;text?:string;action?:React.ReactNode}){
 return <div className="admin-page-intro"><div><div className="admin-eyebrow">{eyebrow||'BILAR DIGITALTECH'}</div><h1>{title}</h1>{text&&<p>{text}</p>}</div>{action&&<div className="admin-page-intro-action">{action}</div>}</div>
}
function Team({data}:any){const[editing,setEditing]=useState<TeamMember|null>(null);return <><PageIntro eyebrow="PESSOAS" title="Equipa" text="Gerir os membros da equipa apresentados no ecossistema Bilar." action={<button className="admin-primary" onClick={()=>setEditing({id:'',name:'',role:'',avatar:'',bio:'',specialty:'',active:true,order:(data.teamMembers||[]).length})}><Plus size={16}/> Adicionar pessoa</button>}/><div className="admin-card-grid">{(data.teamMembers||[]).map((m:TeamMember)=><article className="content-card" key={m.id}><div className="content-card-icon"><Users/></div><div className="content-card-body"><Pill kind={m.active!==false?'green':'gray'}>{m.active!==false?'Activo':'Inactivo'}</Pill><h3>{m.name}</h3><p>{m.role}</p><small>{m.specialty||m.department||'Especialidade não indicada'}</small></div><CardActions onEdit={()=>setEditing(m)} onDelete={()=>data.deleteTeamMember(m.id)}/></article>)}</div>{editing&&<PersonModal kind="team" item={editing} close={()=>setEditing(null)} save={(v:any)=>{editing.id?data.updateTeamMember(editing.id,v):data.addTeamMember(v);setEditing(null)}}/>}</>}
function Careers({data}:any){const[editing,setEditing]=useState<CareerOpening|null>(null);return <><PageIntro eyebrow="TALENTO" title="Carreiras" text="Gerir oportunidades de carreira e recrutamento da Bilar." action={<button className="admin-primary" onClick={()=>setEditing({id:'',title:'',department:'',location:'Moçambique',type:'Full-time',description:'',requirements:[],status:'draft',order:(data.careerOpenings||[]).length})}><Plus size={16}/> Nova vaga</button>}/><div className="admin-card-grid">{(data.careerOpenings||[]).map((c:CareerOpening)=><article className="content-card" key={c.id}><div className="content-card-icon"><BriefcaseBusiness/></div><div className="content-card-body"><Pill kind={c.status==='open'?'green':c.status==='closed'?'gray':'amber'}>{c.status==='open'?'Aberta':c.status==='closed'?'Fechada':'Rascunho'}</Pill><h3>{c.title}</h3><p>{c.department} · {c.location}</p><small>{c.type}</small></div><CardActions onEdit={()=>setEditing(c)} onDelete={()=>data.deleteCareerOpening(c.id)}/></article>)}</div>{editing&&<CareerModal item={editing} close={()=>setEditing(null)} save={(v:any)=>{editing.id?data.updateCareerOpening(editing.id,v):data.addCareerOpening(v);setEditing(null)}}/>}</>}
function Partners({data}:any){const[editing,setEditing]=useState<Partner|null>(null);return <><PageIntro eyebrow="ECOSSISTEMA" title="Parceiros" text="Gerir parceiros estratégicos apresentados pela Bilar." action={<button className="admin-primary" onClick={()=>setEditing({id:'',name:'',category:'Tecnologia',country:'Moçambique',description:'',logo:'',url:'',active:true,order:(data.partners||[]).length})}><Plus size={16}/> Novo parceiro</button>}/><div className="admin-card-grid">{(data.partners||[]).map((p:Partner)=><article className="content-card" key={p.id}><div className="content-card-icon"><Handshake/></div><div className="content-card-body"><Pill kind={p.active!==false?'green':'gray'}>{p.active!==false?'Activo':'Inactivo'}</Pill><h3>{p.name}</h3><p>{p.description||p.category}</p><small>{p.country||'—'}</small></div><CardActions onEdit={()=>setEditing(p)} onDelete={()=>data.deletePartner(p.id)}/></article>)}</div>{editing&&<PartnerModal item={editing} close={()=>setEditing(null)} save={(v:any)=>{editing.id?data.updatePartner(editing.id,v):data.addPartner(v);setEditing(null)}}/>}</>}
function Specialists({data}:any){const[editing,setEditing]=useState<Specialist|null>(null);return <><PageIntro eyebrow="ESPECIALISTAS" title="Especialistas" text="Gerir especialistas e competências técnicas da equipa Bilar." action={<button className="admin-primary" onClick={()=>setEditing({id:'',name:'',role:'',area:'',specialization:'',bio:'',avatar:'',skills:[],technologies:[],active:true,order:(data.specialists||[]).length})}><Plus size={16}/> Novo especialista</button>}/><div className="admin-card-grid">{(data.specialists||[]).map((s:Specialist)=><article className="content-card" key={s.id}><div className="content-card-icon"><UserRoundCog/></div><div className="content-card-body"><Pill kind={s.active!==false?'green':'gray'}>{s.active!==false?'Activo':'Inactivo'}</Pill><h3>{s.name}</h3><p>{s.role}</p><small>{s.specialization||s.area}</small></div><CardActions onEdit={()=>setEditing(s)} onDelete={()=>data.deleteSpecialist(s.id)}/></article>)}</div>{editing&&<PersonModal kind="specialist" item={editing} close={()=>setEditing(null)} save={(v:any)=>{editing.id?data.updateSpecialist(editing.id,v):data.addSpecialist(v);setEditing(null)}}/>}</>}
function PersonModal({kind,item,close,save}:{kind:'team'|'specialist';item:any;close:()=>void;save:(v:any)=>void}){const[f,setF]=useState({...item});return <Modal title={item.id?'Editar pessoa':'Adicionar pessoa'} onClose={close}><div className="form-grid"><Field label="Nome" value={f.name||''} onChange={v=>setF({...f,name:v})}/><Field label="Função" value={f.role||''} onChange={v=>setF({...f,role:v})}/><Field label={kind==='team'?'Especialidade':'Área'} value={f.specialty||f.area||''} onChange={v=>setF({...f,[kind==='team'?'specialty':'area']:v})}/><Field label="Avatar / imagem" value={f.avatar||''} onChange={v=>setF({...f,avatar:v})}/></div><Field label="Biografia" value={f.bio||''} onChange={v=>setF({...f,bio:v})} area/><Field label={kind==='team'?'Competências (uma por linha)':'Tecnologias (uma por linha)'} value={(kind==='team'?(f.skills||[]):(f.technologies||[])).join('\n')} onChange={v=>setF({...f,[kind==='team'?'skills':'technologies']:v.split('\n').map((x:string)=>x.trim()).filter(Boolean)})} area/><label className="check"><input type="checkbox" checked={f.active!==false} onChange={e=>setF({...f,active:e.target.checked})}/> Activo</label><div className="form-actions"><button className="admin-primary" onClick={()=>{const{id,...rest}=f;save(rest)}}><Save size={16}/> Guardar</button></div></Modal>}
function CareerModal({item,close,save}:{item:CareerOpening;close:()=>void;save:(v:any)=>void}){const[f,setF]=useState({...item});return <Modal title={item.id?'Editar vaga':'Nova vaga'} onClose={close}><div className="form-grid"><Field label="Título" value={f.title} onChange={v=>setF({...f,title:v})}/><Field label="Departamento" value={f.department} onChange={v=>setF({...f,department:v})}/><Field label="Localização" value={f.location} onChange={v=>setF({...f,location:v})}/><Field label="Tipo" value={f.type} onChange={v=>setF({...f,type:v})}/></div><Field label="Descrição" value={f.description} onChange={v=>setF({...f,description:v})} area/><Field label="Requisitos (uma por linha)" value={(f.requirements||[]).join('\n')} onChange={v=>setF({...f,requirements:v.split('\n').filter(Boolean)})} area/><label className="admin-field"><span>Estado</span><select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="open">Aberta</option><option value="draft">Rascunho</option><option value="closed">Fechada</option></select></label><Field label="Email de candidatura" value={f.applyEmail||''} onChange={v=>setF({...f,applyEmail:v})}/><div className="form-actions"><button className="admin-primary" onClick={()=>{const{id,...rest}=f;save(rest)}}><Save size={16}/> Guardar</button></div></Modal>}
function PartnerModal({item,close,save}:{item:Partner;close:()=>void;save:(v:any)=>void}){const[f,setF]=useState({...item});return <Modal title={item.id?'Editar parceiro':'Novo parceiro'} onClose={close}><div className="form-grid"><Field label="Nome" value={f.name} onChange={v=>setF({...f,name:v})}/><Field label="Categoria" value={f.category} onChange={v=>setF({...f,category:v})}/><Field label="País" value={f.country||''} onChange={v=>setF({...f,country:v})}/><Field label="URL" value={f.url||''} onChange={v=>setF({...f,url:v})}/></div><Field label="Descrição" value={f.description||''} onChange={v=>setF({...f,description:v})} area/><Field label="Logo / imagem" value={f.logo||''} onChange={v=>setF({...f,logo:v})}/><label className="check"><input type="checkbox" checked={f.active!==false} onChange={e=>setF({...f,active:e.target.checked})}/> Activo</label><div className="form-actions"><button className="admin-primary" onClick={()=>{const{id,...rest}=f;save(rest)}}><Save size={16}/> Guardar</button></div></Modal>}

function LocalOrFirebaseReset({email,setEmail,firebaseReady,onBack,onMessage}:{email:string;setEmail:(v:string)=>void;firebaseReady:boolean;onBack:()=>void;onMessage:(msg:string,ok:boolean)=>void}){
 const d=useSiteData();
 return <div className="admin-reset-box"><div className="admin-auth-form-head"><div className="admin-auth-kicker">RECUPERAÇÃO DE ACESSO</div><h2>Recuperar palavra-passe</h2><p>{firebaseReady?'Introduza o email profissional para receber um link seguro de recuperação.':'O serviço de autenticação ainda não está disponível nesta instalação.'}</p></div><form onSubmit={async e=>{e.preventDefault();const em=email.trim();if(!em){onMessage('Introduza o email profissional.',false);return;}if(!firebaseReady){onMessage('O Firebase ainda não está configurado para esta instalação.',false);return;}const result=await d.resetAdminPassword(em);onMessage(result.message||'Não foi possível concluir a recuperação.',result.ok);}}><Field label="Email profissional" value={email} onChange={setEmail} placeholder="nome@empresa.com"/><button type="submit" className="admin-primary full">Enviar link de recuperação <ArrowLeft size={16} className="admin-reset-arrow"/></button></form><button type="button" className="admin-back-link" onClick={onBack}><ArrowLeft size={15}/> Voltar ao login</button></div>
}

function Dashboard({counts,data,go}:any){const recent=[...data.blogPosts.map((x:any)=>({kind:'Insight',title:x.title,date:x.date,img:x.coverImage})),...data.projects.map((x:any)=>({kind:'Projecto',title:x.title,date:x.date||'Conteúdo actual',img:imgFor(x)}))].slice(0,6);return <div className="admin-dashboard-home"><PageIntro eyebrow="VISÃO GERAL" title={data.adminSettings.welcomeTitle||'Centro de Gestão Bilar'} text={data.adminSettings.welcomeText||'Gira a empresa, o catálogo, os produtos, os projectos, os leads, os conteúdos e as aplicações do ecossistema Bilar.'} action={<a className="admin-primary" href={import.meta.env.BASE_URL} target="_blank">Abrir site <ExternalLink size={16}/></a>}/><div className="admin-stat-grid" style={{display:data.adminSettings.showStats===false?'none':undefined}}>{[['Projectos',counts.projects,'projectos',FolderKanban],['Serviços activos',counts.services,'servicos',BriefcaseBusiness],['Equipa',counts.team,'equipa',Users],['Especialistas',counts.specialists,'especialistas',UserRoundCog],['Insights',counts.posts,'blog',FileText],['Novos contactos',counts.contacts,'contactos',MessageSquare],['Media',counts.media,'media',Images],['Produtos',counts.products,'products',Package],['Fontes de receita',counts.revenue,'receitas',WalletCards]].map(([l,v,id,I]:any)=><button className="admin-stat" key={l} onClick={()=>go(id)}><span className="stat-icon"><I size={19}/></span><div><strong>{v}</strong><span>{l}</span></div><small>Gerir →</small></button>)}</div><div className="admin-grid-2"><section className="admin-panel"><div className="panel-head"><div><div className="admin-eyebrow">CONTEÚDO RECENTE</div><h3>O que está publicado</h3></div><button className="admin-link" onClick={()=>go('media')}>Ver media</button></div><div className="recent-list">{recent.map((x:any,i:number)=><div className="recent-item" key={i}><img src={x.img}/><div><Pill kind="blue">{x.kind}</Pill><strong>{x.title}</strong><small>{x.date}</small></div><Eye size={16}/></div>)}</div></section><section className="admin-panel"><div className="panel-head"><div><div className="admin-eyebrow">ACÇÕES RÁPIDAS</div><h3>Gerir o site</h3></div></div><div className="quick-grid">{[['Novo projecto','projectos',FolderKanban],['Novo insight','blog',FileText],['Novo serviço','servicos',BriefcaseBusiness],['Adicionar pessoa','equipa',Users],['Ver contactos','contactos',MessageSquare],['Biblioteca media','media',Images]].map(([t,id,I]:any)=><button key={t} onClick={()=>go(id)}><I size={18}/><span>{t}</span></button>)}</div><div className="health"><div><span className="dot"/> Site público operacional</div><span>Conteúdo público editável</span></div></section></div></div>}
function Empresa({data}:any){
 const c=data.companyInfo; const[f,setF]=useState(c);
 const baseFields=[['name','Nome da empresa'],['secondaryEmail','Email institucional'],['shortName','Nome curto'],['tagline','Slogan'],['badge','Badge'],['heroTitle','Título principal'],['heroSubtitle','Subtítulo'],['phone','Telefone'],['email','Email'],['whatsappUrl','WhatsApp'],['location','Localização']];
 const socials=[['facebook','Facebook'],['instagram','Instagram'],['linkedin','LinkedIn'],['youtube','YouTube'],['tiktok','TikTok'],['x','X']];
 return <><PageIntro eyebrow="IDENTIDADE" title="Empresa" text="Informações institucionais que alimentam directamente a presença pública da Bilar DigitalTech."/>
 <section className="admin-panel form-panel">
  <div className="admin-logo-note"><BilarLogo size="md" theme="light"/><div><strong>Identidade visual Bilar</strong><span>Altere aqui o conteúdo que será reflectido no site público. Guarde uma vez e a mesma informação passa a ser usada pelo site.</span></div></div>
  <div className="admin-section-title"><strong>Identidade e contacto</strong><span>Dados principais da empresa.</span></div>
  <div className="form-grid">{baseFields.map(([k,l])=><Field key={k} label={l} value={f[k]||''} onChange={v=>setF({...f,[k]:v})}/>)}</div>
  <div className="admin-section-title"><strong>Redes sociais</strong><span>O Super Admin pode gerir estes links aqui. As alterações aparecem nos botões sociais do site público.</span></div>
  <div className="social-admin-grid">{socials.map(([k,l])=><Field key={k} label={l} value={f[k]||''} onChange={v=>setF({...f,[k]:v})} placeholder={`https://${l.toLowerCase()}.com/...`}/>)}</div>
  <ImageField label="Imagem principal do Hero" value={f.heroImage||''} onChange={v=>setF({...f,heroImage:v})}/>
  <div className="admin-section-title"><strong>Sobre Nós — conteúdo público</strong><span>Estas alterações aparecem directamente na página pública.</span></div>
  <ImageField label="Imagem do Sobre Nós" value={f.aboutImage||''} onChange={v=>setF({...f,aboutImage:v})}/>
  <div className="form-grid"><Field label="Título do Sobre Nós" value={f.aboutTitle||''} onChange={v=>setF({...f,aboutTitle:v})}/><Field label="Assinatura" value={f.aboutSignature||''} onChange={v=>setF({...f,aboutSignature:v})}/></div>
  <Field label="Texto do Sobre Nós" value={f.aboutDescription||''} onChange={v=>setF({...f,aboutDescription:v})} area/>
  <Field label="Frase/depoimento do Sobre Nós" value={f.aboutQuote||''} onChange={v=>setF({...f,aboutQuote:v})} area/>
  <Field label="Descrição do footer" value={f.footerDescription||''} onChange={v=>setF({...f,footerDescription:v})} area placeholder="Breve descrição que aparece no rodapé."/>
  <Field label="Links adicionais do footer" value={f.footerNavLinks||''} onChange={v=>setF({...f,footerNavLinks:v})} area placeholder="Um por linha: Nome|URL"/>
  <div className="form-actions"><button className="admin-primary" onClick={()=>data.updateCompanyInfo(f)}><Save size={16}/> Guardar alterações</button></div>
 </section></>}

function Products({data}:any){const[editing,setEditing]=useState<BilarProduct|null>(null);return <><PageIntro eyebrow="ACTIVOS PRÓPRIOS" title="Bilar Products" text="Produtos tecnológicos criados pela Bilar para serem vendidos, licenciados ou usados por muitos clientes." action={<button className="admin-primary" onClick={()=>setEditing({id:'',name:'',category:'Tecnologia',description:'',problem:'',benefits:[],features:[],audience:'',businessModel:'Venda ou licença',price:'Sob consulta',promotion:'',image:'',websiteUrl:'',appUrl:'',supportUrl:'',documentationUrl:'',status:'prototype',featured:true,active:true,extras:{}})}><Plus size={16}/> Novo produto</button>}/><div className="admin-card-grid">{data.bilarProducts.map((p:BilarProduct)=><article className="content-card" key={p.id}><div className="content-card-icon"><Package/></div><div className="content-card-body"><Pill kind={p.active!==false?'green':'gray'}>{p.status==='available'?'Disponível':p.status==='research'?'Pesquisa':p.status==='prototype'?'Protótipo':p.status==='testing'?'Em testes':'Brevemente'}</Pill><h3>{p.name}</h3><p>{p.description}</p><small>{p.businessModel} · {p.audience||'Público a definir'}</small>{data.productOperations.find((x:ProductOperation)=>x.productId===p.id)?.adminUrl&&<a className="admin-link" href={data.productOperations.find((x:ProductOperation)=>x.productId===p.id)?.adminUrl} target="_blank" rel="noreferrer"><ShieldCheck size={14}/> Abrir Admin do produto</a>}</div><CardActions onEdit={()=>setEditing(p)} onDelete={()=>data.deleteProduct(p.id)}/></article>)}</div>{editing&&<ProductModal item={editing} operation={editing.id?data.productOperations.find((x:ProductOperation)=>x.productId===editing.id):undefined} close={()=>setEditing(null)} save={(p:any,op:any)=>{editing.id?data.updateProduct(editing.id,p,op):data.addProduct(p,op);setEditing(null)}}/>}</>}
function ProductModal({item,close,save,operation}:{item:BilarProduct;close:()=>void;save:(product:Omit<BilarProduct,'id'>,operation?:Pick<ProductOperation,'adminUrl'>)=>void;operation?:ProductOperation}){
 const[f,setF]=useState({...item,extras:item.extras||{}});
 const[adminUrl,setAdminUrl]=useState(operation?.adminUrl||'');
 return <Modal title={item.id?'Editar produto':'Novo produto'} onClose={close}>
  <div className="admin-section-title"><strong>Identidade do produto</strong><span>O produto pertence à Bilar, mas a sua operação pode viver num sistema independente.</span></div>
  <div className="form-grid"><Field label="Nome" value={f.name||''} onChange={v=>setF({...f,name:v})}/><Field label="Categoria" value={f.category||''} onChange={v=>setF({...f,category:v})}/><Field label="Público-alvo" value={f.audience||''} onChange={v=>setF({...f,audience:v})}/><Field label="Modelo de negócio" value={f.businessModel||''} onChange={v=>setF({...f,businessModel:v})}/><Field label="Preço" value={f.price||''} onChange={v=>setF({...f,price:v})}/><Field label="Frase promocional" value={f.promotion||''} onChange={v=>setF({...f,promotion:v})}/></div>
  <ImageField label="Imagem principal" value={f.image||''} onChange={v=>setF({...f,image:v})}/>
  <Field label="Descrição" value={f.description||''} onChange={v=>setF({...f,description:v})} area/>
  <Field label="Problema que resolve" value={f.problem||''} onChange={v=>setF({...f,problem:v})} area/>
  <Field label="Funcionalidades (uma por linha)" value={(f.features||[]).join('\n')} onChange={v=>setF({...f,features:v.split('\n').map((x:string)=>x.trim()).filter(Boolean)})} area/>
  <Field label="Benefícios (uma por linha)" value={(f.benefits||[]).join('\n')} onChange={v=>setF({...f,benefits:v.split('\n').map((x:string)=>x.trim()).filter(Boolean)})} area/>
  <div className="admin-section-title"><strong>Ligações do produto</strong><span>Estas ligações permitem que cada produto tenha o seu próprio site, aplicação e administração.</span></div>
  <div className="form-grid"><Field label="Página pública do produto" value={f.websiteUrl||''} onChange={v=>setF({...f,websiteUrl:v})} placeholder="https://produto.bilar..."/><Field label="Aplicação / plataforma" value={f.appUrl||''} onChange={v=>setF({...f,appUrl:v})} placeholder="https://app..."/><Field label="Admin próprio do produto" value={adminUrl} onChange={setAdminUrl} placeholder="https://admin..."/><Field label="Suporte" value={f.supportUrl||''} onChange={v=>setF({...f,supportUrl:v})} placeholder="https://..."/><Field label="Documentação" value={f.documentationUrl||''} onChange={v=>setF({...f,documentationUrl:v})} placeholder="https://..."/></div>
  <label className="admin-field"><span>Estado</span><select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="research">Pesquisa</option><option value="prototype">Protótipo</option><option value="testing">Em testes</option><option value="available">Disponível</option><option value="soon">Brevemente</option></select></label>
  <ContentExtrasEditor value={f.extras} onChange={extras=>setF({...f,extras})}/>
  <label className="check"><input type="checkbox" checked={!!f.featured} onChange={e=>setF({...f,featured:e.target.checked})}/> Destacar no site</label>
  <label className="check"><input type="checkbox" checked={f.active!==false} onChange={e=>setF({...f,active:e.target.checked})}/> Produto activo</label>
  <div className="form-actions">{f.websiteUrl&&<a className="admin-secondary" href={f.websiteUrl} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Página</a>}{f.appUrl&&<a className="admin-secondary" href={f.appUrl} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Aplicação</a>}{adminUrl&&<a className="admin-primary" href={adminUrl} target="_blank" rel="noreferrer"><ShieldCheck size={15}/> Admin do produto</a>}<button className="admin-primary" onClick={()=>{const {id:_,...product}=f;save(product,{adminUrl});}}><Save size={16}/> Guardar produto</button></div>
 </Modal>
}

function Labs({data}:any){
 const[editing,setEditing]=useState<LabProject|null>(null);
 const[newOpen,setNewOpen]=useState(false);
 const drafts=data.labProjects||[];
 const statusText:any={idea:'Ideia',research:'Pesquisa',prototype:'Protótipo',testing:'Em testes',ready:'Pronto'};
 const newProject=()=>setNewOpen(true);
 return <><PageIntro eyebrow="INVESTIGAÇÃO & DESENVOLVIMENTO" title="Bilar Labs" text="Repositório interno de projectos em desenvolvimento. Os colaboradores podem abrir, editar e guardar o trabalho directamente no Firebase." action={<button className="admin-primary" onClick={newProject}><Plus size={16}/> Novo projecto em desenvolvimento</button>}/>
 <div className="admin-grid-2"><section className="admin-panel"><FlaskConical size={24}/><h3>Pipeline de inovação</h3><div className="lab-flow"><Pill kind="blue">1 · Ideia</Pill><span>→</span><Pill kind="blue">2 · Pesquisa</Pill><span>→</span><Pill kind="amber">3 · Protótipo</Pill><span>→</span><Pill kind="amber">4 · Testes</Pill><span>→</span><Pill kind="green">5 · Produto</Pill></div><p>Os projectos ficam guardados no repositório Bilar Labs e podem ser retomados por outros colaboradores autorizados.</p></section>
 <section className="admin-panel"><div className="panel-head"><div><div className="admin-eyebrow">REPOSITÓRIO DE DESENVOLVIMENTO</div><h3>Projectos em desenvolvimento</h3></div><Pill kind="blue">{drafts.length} projectos</Pill></div>{drafts.length?<div className="recent-list">{drafts.map((p:LabProject)=><button type="button" className="recent-item recent-item-button" key={p.id} onClick={()=>setEditing(p)}><span className="stat-icon"><FlaskConical size={17}/></span><div><strong>{p.title}</strong><small>{statusText[p.status]||p.status} · {new Date(p.updatedAt).toLocaleString('pt-PT')}{p.updatedBy?` · ${p.updatedBy}`:''}</small></div><Edit3 size={15}/></button>)}</div>:<Empty title="Ainda não existem projectos em desenvolvimento" text="Crie o primeiro projecto para a equipa poder trabalhar nele."/>}</section></div>
 {newOpen&&<LabProjectModal item={{id:'',title:'',description:'',status:'idea',owner:'',collaborators:[],repositoryUrl:'',demoUrl:'',notes:'',createdAt:'',updatedAt:''}} close={()=>setNewOpen(false)} save={async(p:any)=>{await data.addLabProject(p);setNewOpen(false)}}/>}
 {editing&&<LabProjectModal item={editing} close={()=>setEditing(null)} save={async(p:any)=>{await data.updateLabProject(editing.id,p)}} remove={async()=>{if(confirm('Remover este projecto do repositório?')){await data.deleteLabProject(editing.id);setEditing(null)}}}/>}</>;
}
function LabProjectModal({item,close,save,remove}:{item:LabProject;close:()=>void;save:(p:any)=>Promise<void>;remove?:()=>Promise<void>}){
 const[f,setF]=useState<LabProject>(item); const[busy,setBusy]=useState(false); const[saved,setSaved]=useState(true); const timer=useRef<number|undefined>(undefined);
 useEffect(()=>{if(!item.id)return; setSaved(false); if(timer.current)window.clearTimeout(timer.current); timer.current=window.setTimeout(async()=>{setBusy(true);try{await save({...f,id:undefined});setSaved(true);}finally{setBusy(false)}},900); return()=>{if(timer.current)window.clearTimeout(timer.current)}},[f.title,f.description,f.status,f.owner,f.repositoryUrl,f.demoUrl,f.notes,JSON.stringify(f.collaborators)]);
 const manual=async()=>{setBusy(true);try{await save({...f,id:undefined});setSaved(true);}finally{setBusy(false)}};
 return <Modal title={item.id?'Editar projecto em desenvolvimento':'Novo projecto em desenvolvimento'} onClose={close}><div className="auto-save-bar"><span>{busy?'A guardar...':saved?'Guardado automaticamente':'Alterações por guardar...'}</span><button className="admin-secondary" onClick={manual}><Save size={15}/> Guardar agora</button></div><div className="form-grid"><Field label="Nome do projecto" value={f.title} onChange={v=>setF({...f,title:v})} placeholder="Ex.: Plataforma Bilar Move"/><Field label="Responsável" value={f.owner} onChange={v=>setF({...f,owner:v})} placeholder="Nome do colaborador"/><label className="admin-field"><span>Estado</span><select value={f.status} onChange={e=>setF({...f,status:e.target.value as any})}><option value="idea">Ideia</option><option value="research">Pesquisa</option><option value="prototype">Protótipo</option><option value="testing">Em testes</option><option value="ready">Pronto</option></select></label><Field label="Repositório GitHub" value={f.repositoryUrl||''} onChange={v=>setF({...f,repositoryUrl:v})} placeholder="https://github.com/..."/><Field label="Demo / ambiente" value={f.demoUrl||''} onChange={v=>setF({...f,demoUrl:v})} placeholder="https://..."/></div><Field label="Descrição" value={f.description} onChange={v=>setF({...f,description:v})} area/><Field label="Colaboradores (um por linha)" value={(f.collaborators||[]).join('\n')} onChange={v=>setF({...f,collaborators:v.split('\n').map(x=>x.trim()).filter(Boolean)})} area/><Field label="Notas de desenvolvimento" value={f.notes||''} onChange={v=>setF({...f,notes:v})} area/><div className="form-actions"><button className="admin-primary" onClick={manual}><Save size={16}/> Guardar projecto</button>{f.repositoryUrl&&<a className="admin-secondary" href={f.repositoryUrl} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Abrir repositório</a>}{remove&&<button className="admin-danger" onClick={()=>void remove()}><Trash2 size={15}/> Remover</button>}</div></Modal>}

function Revenue({data}:any){const[editing,setEditing]=useState<RevenueStream|null>(null);return <><PageIntro eyebrow="NEGÓCIO" title="Receitas & Modelo de Negócio" text="Área interna para visualizar e gerir as fontes através das quais a Bilar gera receita." action={<button className="admin-primary" onClick={()=>setEditing({id:'',name:'',type:'Outro',model:'',description:'',active:true})}><Plus size={16}/> Nova fonte de receita</button>}/><div className="admin-card-grid">{data.revenueStreams.map((r:RevenueStream)=><article className="content-card" key={r.id}><div className="content-card-icon">{r.type==='Subscrição'?<Repeat2/>:r.type==='Produto'?<Package/>:<WalletCards/>}</div><div className="content-card-body"><Pill kind={r.active!==false?'green':'gray'}>{r.type}</Pill><h3>{r.name}</h3><p>{r.description||'Fonte de receita da Bilar.'}</p><small><strong>Modelo:</strong> {r.model}</small></div><CardActions onEdit={()=>setEditing(r)} onDelete={()=>data.deleteRevenueStream(r.id)}/></article>)}</div>{editing&&<RevenueModal item={editing} close={()=>setEditing(null)} save={(p:any)=>{editing.id?data.updateRevenueStream(editing.id,p):data.addRevenueStream(p);setEditing(null)}}/>}</>}
function RevenueModal({item,close,save}:any){const[f,setF]=useState(item);return <Modal title={item.id?'Editar fonte de receita':'Nova fonte de receita'} onClose={close}><div className="form-grid"><Field label="Nome" value={f.name||''} onChange={v=>setF({...f,name:v})}/><Field label="Modelo" value={f.model||''} onChange={v=>setF({...f,model:v})}/></div><Field label="Descrição" value={f.description||''} onChange={v=>setF({...f,description:v})} area/><label className="admin-field"><span>Tipo</span><select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option>Serviço</option><option>Produto</option><option>Subscrição</option><option>Manutenção</option><option>Outro</option></select></label><label className="check"><input type="checkbox" checked={f.active!==false} onChange={e=>setF({...f,active:e.target.checked})}/> Activo</label><div className="form-actions"><button className="admin-primary" onClick={()=>save({...f,id:undefined})}><Save size={16}/> Guardar</button></div></Modal>}

function Services({data}:any){const[q,setQ]=useState('');const [editing,setEditing]=useState<Service|null>(null);const list=data.services.filter((x:Service)=>x.title.toLowerCase().includes(q.toLowerCase()));return <><PageIntro eyebrow="CATÁLOGO" title="Serviços" text="Controle o catálogo de soluções que aparece no site público." action={<button className="admin-primary" onClick={()=>setEditing({id:'',title:'',description:'',fullDescription:'',iconName:'Globe',features:[],deliverables:[],active:true,order:list.length,image:'',extras:{}})}><Plus size={16}/> Novo serviço</button>}/><Toolbar q={q} setQ={setQ}/><div className="admin-card-grid">{list.map((s:Service)=><article className="content-card" key={s.id}><div className="content-card-icon"><BriefcaseBusiness/></div><div className="content-card-body"><div><Pill kind={s.active!==false?'green':'gray'}>{s.active!==false?'Activo':'Inactivo'}</Pill></div><h3>{s.title}</h3><p>{s.description}</p><small>{s.features.length} características · {s.deliverables.length} entregáveis</small></div><CardActions onEdit={()=>setEditing(s)} onDelete={()=>data.deleteService(s.id)}/></article>)}</div>{editing&&<ServiceModal item={editing} close={()=>setEditing(null)} save={(p:any)=>{editing.id?data.updateService(editing.id,p):data.addService(p);setEditing(null)}}/>}</>}
function ServiceModal({item,close,save}:any){const[f,setF]=useState({...item,extras:item.extras||{}});return <Modal title={item.id?'Editar serviço':'Novo serviço'} onClose={close}><div className="form-grid"><Field label="Título" value={f.title||''} onChange={v=>setF({...f,title:v})}/><Field label="Ícone" value={f.iconName||''} onChange={v=>setF({...f,iconName:v})}/><Field label="Descrição" value={f.description||''} onChange={v=>setF({...f,description:v})}/><Field label="Preço / condição" value={f.price||''} onChange={v=>setF({...f,price:v})}/></div><Field label="Descrição completa" value={f.fullDescription||''} onChange={v=>setF({...f,fullDescription:v})} area/><ImageField label="Imagem do serviço" value={f.image||''} onChange={v=>setF({...f,image:v})}/><Field label="Características (uma por linha)" value={(f.features||[]).join('\n')} onChange={v=>setF({...f,features:v.split('\n').filter(Boolean)})} area/><Field label="Entregáveis (uma por linha)" value={(f.deliverables||[]).join('\n')} onChange={v=>setF({...f,deliverables:v.split('\n').filter(Boolean)})} area/><ContentExtrasEditor value={f.extras} onChange={extras=>setF({...f,extras})}/><label className="check"><input type="checkbox" checked={f.active!==false} onChange={e=>setF({...f,active:e.target.checked})}/> Publicar serviço no site</label><div className="form-actions"><button className="admin-primary" onClick={()=>save({...f,id:undefined})}><Save size={16}/> Guardar</button></div></Modal>}
function Projects({data}:any){const[q,setQ]=useState('');const[editing,setEditing]=useState<Project|null>(null);const list=data.projects.filter((x:Project)=>x.title.toLowerCase().includes(q.toLowerCase()));return <><PageIntro eyebrow="PORTFÓLIO" title="Projectos" text="Veja as capas reais, estado editorial e informação dos projectos apresentados ao público." action={<button className="admin-primary" onClick={()=>setEditing({id:'',title:'Novo projecto',category:'Websites',subtitle:'',description:'',imageType:'gestao',technologies:[],client:'',status:'draft',featured:false,metrics:'',image:'',gallery:[],link:'',extras:{}})}><Plus size={16}/> Novo projecto</button>}/><Toolbar q={q} setQ={setQ}/><div className="admin-project-grid">{list.map((p:Project)=><article className="project-admin-card" key={p.id}><img src={imgFor(p)} /><div className="project-overlay"><Pill kind={p.status==='published'?'green':p.status==='archived'?'gray':'amber'}>{statusLabel(p.status||'published')}</Pill>{p.featured&&<Pill kind="blue">Destaque</Pill>}</div><div className="project-admin-body"><div className="admin-eyebrow">{p.category}</div><h3>{p.title}</h3><p>{p.description}</p><div className="tag-row">{p.technologies.slice(0,4).map(t=><span key={t}>{t}</span>)}</div><CardActions onEdit={()=>setEditing(p)} onDelete={()=>data.deleteProject(p.id)}/></div></article>)}</div>{editing&&<ProjectModal item={editing} close={()=>setEditing(null)} save={(p:any)=>{editing.id?data.updateProject(editing.id,p):data.addProject(p);setEditing(null)}}/>}</>}
function ProjectModal({item,close,save}:any){const[f,setF]=useState({...item,extras:item.extras||{}});return <Modal title={item.id?'Editar projecto':'Novo projecto'} onClose={close}><div className="form-grid"><Field label="Nome" value={f.title||''} onChange={v=>setF({...f,title:v})}/><Field label="Subtítulo" value={f.subtitle||''} onChange={v=>setF({...f,subtitle:v})}/><Field label="Cliente" value={f.client||''} onChange={v=>setF({...f,client:v})}/><Field label="Métrica" value={f.metrics||''} onChange={v=>setF({...f,metrics:v})}/><Field label="Frase promocional" value={f.promotion||''} onChange={v=>setF({...f,promotion:v})}/><Field label="Data" value={f.date||''} onChange={v=>setF({...f,date:v})}/><Field label="Link do projecto" value={f.link||''} onChange={v=>setF({...f,link:v})} placeholder="https://..."/></div><ImageField label="Capa do projecto" value={f.image||''} onChange={v=>setF({...f,image:v})}/><GalleryField label="Galeria do projecto" value={f.gallery||[]} onChange={v=>setF({...f,gallery:v})}/><Field label="Descrição" value={f.description||''} onChange={v=>setF({...f,description:v})} area/><Field label="Tecnologias (separadas por vírgula)" value={(f.technologies||[]).join(', ')} onChange={v=>setF({...f,technologies:v.split(',').map((x:string)=>x.trim()).filter(Boolean)})}/><div className="form-grid"><label className="admin-field"><span>Categoria</span><select value={f.category} onChange={e=>setF({...f,category:e.target.value})}>{['Websites','Aplicações','Sistemas','Design'].map(x=><option key={x}>{x}</option>)}</select></label><label className="admin-field"><span>Estado</span><select value={f.status||'draft'} onChange={e=>setF({...f,status:e.target.value})}><option value="published">Publicado</option><option value="draft">Rascunho</option><option value="archived">Arquivado</option></select></label></div><ContentExtrasEditor value={f.extras} onChange={extras=>setF({...f,extras})}/><label className="check"><input type="checkbox" checked={!!f.featured} onChange={e=>setF({...f,featured:e.target.checked})}/> Mostrar em destaque no site</label><div className="form-actions"><button className="admin-primary" onClick={()=>save({...f,id:undefined})}><Save size={16}/> Guardar projecto</button></div></Modal>}
function Blog({data}:any){const[editing,setEditing]=useState<BlogPost|null>(null);return <><PageIntro eyebrow="EDITORIAL" title="Insights Tecnológicos" text="Crie, edite e publique artigos com capa, resumo, autor, tags e estado editorial." action={<button className="admin-primary" onClick={()=>setEditing({id:'',title:'',slug:'',excerpt:'',content:[],category:'Tecnologia & IA',author:{name:'George Fernando Bilar',role:'CEO & Fundador',avatar:'/bilar_ceo_profile_final.webp'},date:new Date().toLocaleDateString('pt-PT'),readTime:'5 min de leitura',coverImage:'/bilar_hero_bilar_office.webp',tags:[],likes:0,commentsCount:0,status:'draft',extras:{}})}><Plus size={16}/> Novo insight</button>}/><div className="admin-blog-grid">{data.blogPosts.map((p:BlogPost)=><article className="blog-admin-card" key={p.id}><img src={p.coverImage}/><div className="blog-admin-body"><div><Pill kind={p.status==='published'?'green':p.status==='archived'?'gray':'amber'}>{statusLabel(p.status||'published')}</Pill><span>{p.date}</span></div><h3>{p.title}</h3><p>{p.excerpt}</p><small>{p.author.name} · {p.readTime}</small><div className="card-actions"><button onClick={()=>setEditing(p)}><Edit3 size={15}/> Editar</button><button className="danger-text" onClick={()=>data.deleteBlogPost(p.id)}><Trash2 size={15}/> Remover</button></div></div></article>)}</div>{editing&&<BlogModal item={editing} close={()=>setEditing(null)} save={(p:any)=>{editing.id?data.updateBlogPost(editing.id,p):data.addBlogPost(p);setEditing(null)}}/>}</>}
function BlogModal({item,close,save}:any){const[f,setF]=useState({...item,extras:item.extras||{}});return <Modal title={item.id?'Editar insight':'Novo insight'} onClose={close}><div className="form-grid"><Field label="Título" value={f.title||''} onChange={v=>setF({...f,title:v})}/><Field label="Slug" value={f.slug||''} onChange={v=>setF({...f,slug:v})}/><Field label="Data" value={f.date||''} onChange={v=>setF({...f,date:v})}/><Field label="Tempo de leitura" value={f.readTime||''} onChange={v=>setF({...f,readTime:v})}/><Field label="Autor" value={f.author?.name||''} onChange={v=>setF({...f,author:{...(f.author||{}),name:v}})}/><Field label="Tags (vírgulas)" value={(f.tags||[]).join(', ')} onChange={v=>setF({...f,tags:v.split(',').map((x:string)=>x.trim()).filter(Boolean)})}/></div><ImageField label="Imagem de capa" value={f.coverImage||''} onChange={v=>setF({...f,coverImage:v})}/><Field label="Resumo" value={f.excerpt||''} onChange={v=>setF({...f,excerpt:v})} area/><Field label="Conteúdo (um parágrafo por linha)" value={(f.content||[]).join('\n')} onChange={v=>setF({...f,content:v.split('\n').filter(Boolean)})} area/><div className="form-grid"><label className="admin-field"><span>Categoria</span><select value={f.category} onChange={e=>setF({...f,category:e.target.value})}>{['Tecnologia & IA','Gestão & Negócios','Transformação Digital','História Bilar'].map(x=><option key={x}>{x}</option>)}</select></label><label className="admin-field"><span>Estado</span><select value={f.status||'draft'} onChange={e=>setF({...f,status:e.target.value,publishedAt:e.target.value==='published'?new Date().toISOString():f.publishedAt})}><option value="published">Publicado</option><option value="draft">Rascunho</option><option value="archived">Arquivado</option></select></label></div><ContentExtrasEditor value={f.extras} onChange={extras=>setF({...f,extras})}/><div className="form-actions"><button className="admin-primary" onClick={()=>save({...f,id:undefined})}><Save size={16}/> Guardar publicação</button></div></Modal>}
function Media({data}:any){const file=useRef<HTMLInputElement>(null);const[preview,setPreview]=useState<string|null>(null);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const assets=useMemo(()=>{const fromProjects=data.projects.map((p:Project)=>({id:'p-'+p.id,name:p.title,url:imgFor(p),type:'project',createdAt:p.date||'Conteúdo existente'}));const fromBlog=data.blogPosts.map((p:BlogPost)=>({id:'b-'+p.id,name:p.title,url:p.coverImage,type:'blog',createdAt:p.date}));const fromServices=data.services.filter((p:Service)=>p.image).map((p:Service)=>({id:'s-'+p.id,name:p.title,url:p.image,type:'institutional',createdAt:'Conteúdo existente'}));const fromTeam=data.teamMembers.map((p:TeamMember)=>({id:'t-'+p.id,name:p.name,url:p.avatar,type:'team',createdAt:'Conteúdo existente'}));return [...data.mediaAssets,...fromProjects,...fromBlog,...fromServices,...fromTeam]},[data.mediaAssets,data.projects,data.blogPosts,data.services,data.teamMembers]);const upload=async(e:any)=>{const f=e.target.files?.[0];if(!f)return;if(!cloudinaryConfigured){setError('Uploads gratuitos requerem a configuração do Cloudinary. Pode usar “Usar URL” enquanto isso.');return;}if(!f.type.startsWith('image/')||f.size>10*1024*1024){setError('Escolha uma imagem até 10 MB.');return;}setBusy(true);setError('');try{const url=await uploadOptimizedImage(f);await data.addMedia({name:f.name,url,type:'institutional'});setPreview(url);}catch(e:any){setError(e?.message==='upload-timeout'?'O carregamento ultrapassou 30 s. Verifique a ligação ou o Cloudinary.':'Falha no upload. Verifique a configuração do Cloudinary.');}finally{setBusy(false);e.target.value='';}};return <><PageIntro eyebrow="BIBLIOTECA VISUAL" title="Media" text="Galeria visual dos recursos já utilizados no site. Clique numa imagem para ampliar." action={<><input ref={file} hidden type="file" accept="image/*,.svg" onChange={upload}/><button className="admin-primary" onClick={()=>file.current?.click()} disabled={busy}><Upload size={16}/> {busy?'A carregar...':'Adicionar imagem'}</button></>}/>{error&&<div className="admin-error">{error}</div>}<div className="media-toolbar"><span>{assets.length} recursos visuais disponíveis</span><div className="legend"><Pill kind="blue">Projectos</Pill><Pill kind="green">Equipa</Pill><Pill kind="amber">Insights</Pill></div></div><div className="media-grid">{assets.map((a:any)=><article className="media-card" key={a.id}><button onClick={()=>setPreview(a.url)}><img src={a.url} alt={a.name}/><span><Eye size={16}/> Ampliar</span></button><div><strong>{a.name}</strong><small>{a.type} · {a.createdAt}</small>{!a.id.startsWith('p-')&&!a.id.startsWith('b-')&&!a.id.startsWith('s-')&&!a.id.startsWith('t-')&&<button className="danger-text" onClick={()=>data.deleteMedia(a.id)}><Trash2 size={14}/> Remover</button>}</div></article>)}</div>{preview&&<Modal title="Pré-visualização" onClose={()=>setPreview(null)}><div className="image-preview"><img src={preview}/></div></Modal>}</>}
function Contacts({data}:any){return <><PageIntro eyebrow="INBOX" title="Contactos" text="Mensagens recebidas pelo site, com estados para organizar o atendimento."/><div className="admin-panel table-panel">{data.contactMessages.length?<table><thead><tr><th>Lead</th><th>Pedido</th><th>Mensagem</th><th>Data</th><th>Estado</th><th></th></tr></thead><tbody>{data.contactMessages.map((m:any)=><tr key={m.id}><td><strong>{m.name}</strong><small>{m.email}</small><small>{m.company||'Particular'} · {m.country||'—'}</small></td><td><Pill kind="blue">{m.interestType||'Serviço'}</Pill><small>{m.budget||'Orçamento não indicado'} · {m.timeline||'Prazo não indicado'}</small></td><td>{m.message}</td><td>{new Date(m.createdAt).toLocaleString('pt-PT')}</td><td><select value={m.status} onChange={e=>data.updateContactStatus(m.id,e.target.value)}><option value="new">Novo</option><option value="read">Lido</option><option value="replied">Respondido</option><option value="archived">Arquivado</option></select></td><td><button className="icon-btn danger" onClick={()=>data.deleteContactMessage(m.id)}><Trash2 size={15}/></button></td></tr>)}</tbody></table>:<Empty title="Ainda não existem mensagens" text="Quando o formulário público começar a receber contactos, eles aparecerão aqui."/>}</div></>}
function UsersAdmin({data}:any){
 const[create,setCreate]=useState(false);const[name,setName]=useState('');const[email,setEmail]=useState('');const[role,setRole]=useState<AdminRole>('Editor');const[error,setError]=useState('');const[busy,setBusy]=useState(false);const[credentials,setCredentials]=useState<any>(null);
 const reset=()=>{setCreate(false);setName('');setEmail('');setRole('Editor');setError('')};
 const save=async()=>{setError('');if(!name.trim()||!email.trim()){setError('Preencha nome e email.');return;}setBusy(true);try{const result=await data.createAdminAccess(name,email,role);setCredentials({...result,name:name.trim()});reset();}catch(e:any){setError(e?.message||'Não foi possível criar o utilizador.');}finally{setBusy(false)}};
 const share=async()=>{if(!credentials)return;const text=`Bilar DigitalTech Solutions\n\nACESSO À GESTÃO BILAR\nNome: ${credentials.name||'Colaborador'}\nEmail: ${credentials.email}\nFunção: ${credentials.role}\n\nPalavra-passe temporária: ${credentials.tempPassword}\n\n1. Abra o endereço abaixo.\n2. Entre com o email e a palavra-passe temporária.\n3. No primeiro acesso, o sistema vai obrigar a criar uma nova palavra-passe.\n\n${credentials.inviteUrl}\n\nConfirme também o email quando receber a mensagem do Firebase.\n\nIdeias que conectam. Soluções que transformam.`;if(navigator.share){try{await navigator.share({title:'Acesso — Gestão Bilar',text,url:credentials.inviteUrl});return}catch{}}await navigator.clipboard?.writeText(text);alert('Credenciais copiadas. Pode enviá-las por WhatsApp, SMS, Facebook, email ou outro canal.');};
 const copy=async()=>{if(!credentials)return;await navigator.clipboard?.writeText(`Bilar DigitalTech Solutions\nACESSO À GESTÃO BILAR\nNome: ${credentials.name}\nEmail: ${credentials.email}\nFunção: ${credentials.role}\nPalavra-passe temporária: ${credentials.tempPassword}\n${credentials.inviteUrl}\n\nNo primeiro acesso, altere a palavra-passe.`);alert('Credenciais copiadas para a área de transferência.');};
 return <><PageIntro eyebrow="ACESSOS" title="Utilizadores & Permissões" text="O Super Admin cria a conta e o sistema gera automaticamente uma palavra-passe temporária. No primeiro acesso, o utilizador é obrigado a criar uma nova palavra-passe." action={<button className="admin-primary" onClick={()=>setCreate(true)}><Plus size={16}/> Criar utilizador</button>}/>
 <section className="admin-panel access-guide"><div><div className="admin-eyebrow">FLUXO SPARK · SEM CLOUD FUNCTIONS</div><h3>Credenciais automáticas e primeiro acesso protegido</h3><p>1. Super Admin cria → 2. sistema gera palavra-passe temporária → 3. credenciais são partilhadas → 4. utilizador entra → 5. sistema obriga a alterar a palavra-passe → 6. email é confirmado.</p></div><div className="access-role-grid"><span><ShieldCheck size={16}/> Super Admin · tudo</span><span><Edit3 size={16}/> Admin · gestão</span><span><FileText size={16}/> Editor · conteúdos</span><span><Users size={16}/> Team Manager · equipa</span></div></section>
 <section className="admin-panel table-panel"><div className="panel-head"><div><div className="admin-eyebrow">CONTAS</div><h3>Contas autorizadas</h3></div><Pill kind="green">{data.adminUsers.length} contas</Pill></div><table><thead><tr><th>Nome</th><th>Email</th><th>Função</th><th>Estado</th><th>Acção</th></tr></thead><tbody>{data.adminUsers.map((u:any)=><tr key={u.id}><td><strong>{u.name}</strong></td><td>{u.username||u.email}</td><td><Pill kind="blue">{u.role}</Pill></td><td><Pill kind={u.active?'green':'gray'}>{u.active?'Activo':'Inactivo'}</Pill></td><td><button className="admin-secondary" onClick={async()=>{try{setBusy(true);const r=await data.resendAdminCredentials(u.id);alert(`Foi enviado um email de recuperação para ${r.email}. Por segurança, a palavra-passe actual não pode ser mostrada novamente.`)}catch(e:any){alert(e?.message||'Não foi possível enviar a recuperação.')}finally{setBusy(false)}}}><Mail size={14}/> {busy?'A enviar...':'Recuperar acesso'}</button></td></tr>)}</tbody></table></section>
 {create&&<Modal title="Criar utilizador" onClose={reset}><div className="access-modal-note"><ShieldCheck size={20}/><div><strong>A palavra-passe é criada automaticamente</strong><p>O sistema gera uma palavra-passe temporária forte. O utilizador entra com ela apenas no primeiro acesso e depois é obrigado a criar uma nova. Tudo funciona no Firebase Spark, sem Cloud Functions.</p></div></div><div className="form-grid"><Field label="Nome completo" value={name} onChange={setName} placeholder="Nome do colaborador"/><Field label="Email profissional" value={email} onChange={setEmail} placeholder="nome@empresa.com"/></div><label className="admin-field"><span>Função</span><select value={role} onChange={e=>setRole(e.target.value as any)}><option value="Admin">Admin</option><option value="Editor">Editor</option><option value="Team Manager">Team Manager</option></select></label>{error&&<div className="admin-error">{error}</div>}<div className="form-actions"><button className="admin-primary" onClick={save} disabled={busy}><Plus size={16}/> {busy?'A criar conta...':'Criar conta'}</button></div></Modal>}
 {credentials&&<Modal title="Conta criada com sucesso" onClose={()=>setCredentials(null)}><div className="credentials-success"><ShieldCheck size={24}/><div><strong>Guarde estas credenciais.</strong><p>A palavra-passe temporária é mostrada apenas agora. Depois do primeiro login, o utilizador terá de a substituir por uma palavra-passe nova.</p></div></div><div className="credential-box"><span>Nome</span><strong>{credentials.name}</strong><span>Email</span><strong>{credentials.email}</strong><span>Função</span><strong>{credentials.role}</strong><span>Palavra-passe temporária</span><strong>{credentials.tempPassword}</strong><span>Endereço de acesso</span><strong style={{wordBreak:'break-all'}}>{credentials.inviteUrl}</strong></div><div className="form-actions"><button className="admin-primary" onClick={share}><ExternalLink size={16}/> Partilhar credenciais</button><button className="admin-secondary" onClick={copy}><Download size={16}/> Copiar credenciais</button><button className="admin-secondary" onClick={()=>setCredentials(null)}>Fechar</button></div></Modal>}
 </>}

function FirstPasswordChangeScreen({onDone,onLogout}:{onDone:()=>void;onLogout:()=>void}){const d=useSiteData();const[pass,setPass]=useState('');const[confirm,setConfirm]=useState('');const[err,setErr]=useState('');const[busy,setBusy]=useState(false);const save=async()=>{setErr('');if(pass.length<8){setErr('A nova palavra-passe deve ter pelo menos 8 caracteres.');return;}if(pass!==confirm){setErr('As palavras-passe não coincidem.');return;}setBusy(true);try{const r=await d.changeFirstPassword(pass);if(r.ok)onDone();else setErr(r.message||'Não foi possível alterar a palavra-passe.');}finally{setBusy(false)}};return <div className="admin-auth admin-auth-register"><div className="auth-register-frame"><section className="auth-register-visual"><div className="auth-register-visual-overlay"/><div className="auth-register-visual-content"><BilarLogo size="sm" theme="dark"/><span className="auth-register-kicker">BILAR DIGITALTECH SOLUTIONS</span><h2>Primeiro acesso.<br/><em>Crie a sua palavra-passe.</em></h2><p>Por segurança, a palavra-passe temporária criada pelo Super Admin só pode ser usada no primeiro acesso.</p><div className="auth-register-badges"><span><ShieldCheck size={15}/> Protecção activa</span><span><LockKeyhole size={15}/> Troca obrigatória</span></div><div className="auth-register-caption">GESTÃO INTERNA · BILAR DIGITALTECH SOLUTIONS</div></div></section><section className="auth-register-panel"><div className="auth-register-form-head"><span>PRIMEIRO ACESSO</span><h1>Alterar palavra-passe</h1><p>Escolha agora a palavra-passe definitiva da sua conta.</p></div>{err&&<div className="admin-error">{err}</div>}<form className="auth-register-form" onSubmit={e=>{e.preventDefault();void save();}}><PasswordField label="Nova palavra-passe" value={pass} onChange={setPass} placeholder="Mínimo de 8 caracteres"/><PasswordField label="Confirmar nova palavra-passe" value={confirm} onChange={setConfirm} placeholder="Repita a nova palavra-passe"/><button type="submit" className="admin-primary full auth-register-submit" disabled={busy}>{busy?'A guardar...':'Guardar nova palavra-passe'} <ArrowLeft size={16}/></button></form><button type="button" className="admin-back-link" onClick={onLogout}><LogOut size={15}/> Terminar sessão</button><div className="auth-register-foot">Bilar DigitalTech Solutions · Centro de Gestão</div></section></div></div>}

function SettingsAdmin({data}:any){const ref=useRef<HTMLInputElement>(null);const a=data.adminSettings||{};return <><PageIntro eyebrow="SISTEMA" title="Configurações" text="Controlo da experiência administrativa, Firebase, backup e ligação às aplicações da Bilar."/><div className="settings-grid"><section className="admin-panel setting-card"><Settings/><h3>Aparência da Gestão</h3><p>Escolha o fundo do login e do Dashboard e ajuste a densidade do painel sem alterar a identidade Bilar.</p><ImageField label="Fundo do ecrã de login" value={a.loginBackground||''} onChange={(v:string)=>data.updateAdminSettings({loginBackground:v})}/><ImageField label="Papel de parede da área de gestão" value={a.dashboardBackground||''} onChange={(v:string)=>data.updateAdminSettings({dashboardBackground:v})}/><div className="form-grid"><Field label="Título do Dashboard" value={a.welcomeTitle||''} onChange={(v:string)=>data.updateAdminSettings({welcomeTitle:v})}/><Field label="Texto do Dashboard" value={a.welcomeText||''} onChange={(v:string)=>data.updateAdminSettings({welcomeText:v})}/></div><label className="admin-field"><span>Densidade</span><select value={a.density||'comfortable'} onChange={e=>data.updateAdminSettings({density:e.target.value})}><option value="comfortable">Confortável</option><option value="compact">Compacta</option></select></label><label className="admin-field"><span>Layout do centro de gestão</span><select value={a.dashboardLayout||'corporate'} onChange={e=>data.updateAdminSettings({dashboardLayout:e.target.value as 'corporate'|'operations'})}><option value="corporate">Corporativo</option><option value="operations">Centro de Operações</option></select></label><label className="check"><input type="checkbox" checked={a.showStats!==false} onChange={e=>data.updateAdminSettings({showStats:e.target.checked})}/> Mostrar indicadores no Dashboard</label></section><section className="admin-panel setting-card"><ShieldCheck/><h3>Ligação Firebase</h3><p>{data.firebaseReady?'Firebase está configurado. O site público lê o estado no Firestore e a Gestão usa Firebase Authentication.':'Firebase ainda não está configurado. O pacote inclui a estrutura de produção, mas é necessário preencher o .env.local com os dados do projecto Firebase antes de publicar.'}</p><div className="health"><div><span className="dot" style={{background:data.firebaseReady?'#10b981':'#f59e0b'}}/> {data.firebaseReady?'Ligação pronta':'Configuração pendente'}</div></div></section><section className="admin-panel setting-card"><Download/><h3>Backup</h3><p>Exporte os conteúdos actuais para JSON e restaure-os quando necessário.</p><div className="form-actions"><button className="admin-primary" onClick={data.exportBackupJson}><Download size={15}/> Exportar</button><input hidden ref={ref} type="file" accept="application/json" onChange={e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{if(!data.importBackupJson(r.result as string))alert('Backup inválido.')};r.readAsText(f)}}/><button className="admin-secondary" onClick={()=>ref.current?.click()}>Importar</button></div></section><section className="admin-panel setting-card"><RefreshCw/><h3>Restaurar conteúdo inicial</h3><p>Remove alterações do estado do site e volta ao conteúdo real mínimo preparado para lançamento.</p><button className="admin-danger" onClick={()=>{if(confirm('Restaurar o conteúdo inicial?'))data.resetAllToDefaults()}}><RefreshCw size={15}/> Restaurar padrões</button></section></div></>}
function Toolbar({q,setQ}:{q:string;setQ:(x:string)=>void}){return <div className="admin-toolbar"><div className="admin-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pesquisar..."/></div><span>Dados reais desta instalação</span></div>}
function CardActions({onEdit,onDelete}:{onEdit:()=>void;onDelete:()=>void}){return <div className="card-actions"><button onClick={onEdit}><Edit3 size={15}/> Editar</button><button className="danger-text" onClick={()=>{if(confirm('Remover este conteúdo?'))onDelete()}}><Trash2 size={15}/> Remover</button></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="admin-empty"><Images size={28}/><h3>{title}</h3><p>{text}</p></div>}
